 * The earliest UTC instant whose wall-clock reading in `timeZone` is at or
 * after the given local date-time. For a time skipped by a DST jump this is
 * the moment the clocks jump; for a repeated time, its first occurrence.
 */
function zonedToUtc(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): Date {
  const wall = Date.UTC(year, month - 1, day, hour, 0, 0, 0);
  const candidates = new Set<number>();
  for (const probe of [wall - DAY_MS, wall, wall + DAY_MS]) {
    candidates.add(wall - zoneOffsetMs(new Date(probe), timeZone));
  }
  const exact = [...candidates]
    .filter((instant) => wallClock(instant, timeZone) === wall)
    .sort((a, b) => a - b);
  if (exact.length > 0) return new Date(exact[0]!);

  // The wall time does not exist (skipped by a DST transition): take the
  // first instant after which the local clock reads past it.
  let low = Math.min(...candidates) - 3 * HOUR_MS;
  let high = Math.max(...candidates) + 3 * HOUR_MS;
